// Theme lineage viewer — chronological family tree for a free-text theme.
//
// Loads:
//   - themes-manifest.json  (sibling of this page; lists generated themes)
//   - themes/<slug>/lineage.json  (per-theme tree, generated by build_theme_lineage.py)
//
// Y axis = year (rank-based: each unique year occupies one row of equal height
// regardless of calendar gaps). X axis = selectable: rank / citation_log /
// genealogy / centrality / venue / novelty. Edges = parent (older, top) →
// child (newer, bottom).
//
// Security:
//   - SLUG_RE is the same character class enforced server-side by
//     paperpilot/scripts/_common.theme_slug(). Validated TWICE: when reading
//     the URL param and when writing it back via the picker. Belt-and-braces
//     against path traversal in the fetch URL.
//   - Tooltip rationale uses textContent (NOT innerHTML) — LLM-generated
//     strings are untrusted.
const { escapeHtml, formatStars } = window.PP;

// Mirror of paperpilot/scripts/_common._SLUG_ALLOWED_RE / theme_slug() output.
const SLUG_RE = /^[a-z0-9-]+$/;

const ALL_RELATIONS = ["supersedes", "successor", "extends", "ablation", "baseline_only", "contrasts"];
const DEFAULT_RELATIONS = ["supersedes", "successor", "extends", "ablation", "contrasts"];
const RELATION_LABEL_JA = {
  supersedes: "置換", successor: "後継", extends: "拡張",
  ablation: "分析", baseline_only: "比較", contrasts: "対立",
};

// X-axis modes. theme.js is the source of truth — the toolbar pill group
// is rendered from this list so labels / icons / order can never drift
// from the layout logic.
const X_AXIS_MODES = ["rank", "citation_log", "genealogy", "centrality", "venue", "novelty"];
const DEFAULT_X_AXIS_MODE = "rank";

// Pill button label + icon + tooltip per mode. The tooltip mirrors the
// concise meaning shown in the canvas-top axis legend.
const X_AXIS_BUTTON = {
  rank:         { icon: "📊", label: "順位",   title: "年内の引用数ランキング (既定)" },
  citation_log: { icon: "📈", label: "log引用", title: "log(引用数+1) — 連続軸" },
  genealogy:    { icon: "🌳", label: "系譜",   title: "親論文の平均 X に寄せる" },
  centrality:   { icon: "⭐", label: "中心性", title: "PageRank — テーマのハブ論文を左に" },
  venue:        { icon: "🏛", label: "会議格", title: "Tier1 → Tier2 → Tier3 → 未査読" },
  novelty:      { icon: "💥", label: "新規性", title: "supersedes/contrasts=破壊的、extends/successor=漸進的" },
};

// Footer hint text per mode. Updated dynamically when the user toggles the
// selector so the legend stays honest about what the horizontal position
// actually encodes for the current view.
const X_AXIS_HINT = {
  rank:         "Y 軸: 年 · X 軸: 年内の引用ランク (左ほど高被引用) · ホバー → 分類理由",
  citation_log: "Y 軸: 年 · X 軸: log(引用数+1) (連続軸 / 左ほど高被引用) · ホバー → 分類理由",
  genealogy:    "Y 軸: 年 · X 軸: 系譜近接 (親論文の平均 X に寄せる) · ホバー → 分類理由",
  centrality:   "Y 軸: 年 · X 軸: PageRank (左ほどテーマ中心のハブ論文) · ホバー → 分類理由",
  venue:        "Y 軸: 年 · X 軸: 会議格 (Tier1 → Tier2 → Tier3 → 未査読) · ホバー → 分類理由",
  novelty:      "Y 軸: 年 · X 軸: 新規性 ↔ 改良性 (左=破壊的、右=漸進的) · ホバー → 分類理由",
};

// Short "← left ... right →" pair shown in the canvas-top axis legend.
// Kept separate from the verbose X_AXIS_HINT so the canvas legend stays
// terse enough to scan at a glance.
const X_AXIS_LEGEND = {
  rank:         { left: "高被引用",       right: "低被引用" },
  citation_log: { left: "log(高被引用)",  right: "log(低被引用)" },
  genealogy:    { left: "同系統の親論文", right: "別系統 / 末葉" },
  centrality:   { left: "テーマのハブ",   right: "周辺" },
  venue:        { left: "Tier1 (一流)",   right: "未査読" },
  novelty:      { left: "破壊的革新",     right: "漸進的改良" },
};

const NODE_W = 260;
// Match `.node-card--theme { min-height: 200px }`. Earlier #79 used
// 216 to leave a buffer for tall cards that would otherwise clip
// inside the foreignObject viewport, but #93 enabled
// `foreignObject overflow="visible"` so cards can grow beyond the
// declared height without clipping. The 16 px buffer was visible as
// a "frame mismatch" — edges connected at the bottom of the
// foreignObject (216) instead of the visible card bottom (200),
// leaving 16 px of empty space between the card border and the
// edge endpoint. Aligning NODE_H to the actual card height makes
// edges land exactly on the card's bottom edge.
const NODE_H = 200;
const ROW_GAP = 80;        // vertical gap between year rows
const SIBLING_GAP = 28;    // horizontal gap between within-year siblings
const PADDING = 56;
const YEAR_LABEL_W = 84;   // left gutter reserved for year axis labels

const SVG_NS = "http://www.w3.org/2000/svg";
const XHTML_NS = "http://www.w3.org/1999/xhtml";

const STORAGE_KEY = "pp.theme.prefs";

const UNKNOWN_YEAR = "__unknown__";

function loadPrefs() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}
function savePrefs() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      visibleRelations: [...state.visibleRelations],
      xAxisMode: state.xAxisMode,
    }));
  } catch { /* localStorage disabled */ }
}

const prefs = loadPrefs();
const state = {
  data: null,
  manifest: [],
  currentSlug: null,
  visibleRelations: new Set(
    Array.isArray(prefs?.visibleRelations) && prefs.visibleRelations.length > 0
      ? prefs.visibleRelations.filter((r) => ALL_RELATIONS.includes(r))
      : DEFAULT_RELATIONS,
  ),
  // #61: search query (lowercased). Empty string = no filter applied.
  searchQuery: "",
  // #62: year-range filter. null/null = no filter applied.
  yearRange: { min: null, max: null },
  // X-axis encoding mode. Validated against allowlist before use because
  // localStorage is user-controlled and bad values would silently corrupt
  // layout.
  xAxisMode: typeof prefs?.xAxisMode === "string" && X_AXIS_MODES.includes(prefs.xAxisMode)
    ? prefs.xAxisMode
    : DEFAULT_X_AXIS_MODE,
};

// #61: matchesSearch — case-insensitive needle in title / authors / venue.
// Returns true when the query is empty so an empty box keeps everything
// visible. Pulled out so render() and tests can share the same predicate.
function matchesSearch(node, q) {
  if (!q) return true;
  const needle = q.toLowerCase();
  if ((node.title || "").toLowerCase().includes(needle)) return true;
  if ((node.venue || "").toLowerCase().includes(needle)) return true;
  for (const a of node.authors || []) {
    if (typeof a === "string" && a.toLowerCase().includes(needle)) return true;
  }
  return false;
}

// #62: matchesYear — true when node.year is within [min, max] inclusive.
// Null bounds (no filter) and unknown years (year not numeric) both pass.
function matchesYear(node, min, max) {
  if (min == null && max == null) return true;
  const y = node.year;
  if (typeof y !== "number") return true; // unknown-year nodes always shown
  if (min != null && y < min) return false;
  if (max != null && y > max) return false;
  return true;
}

const els = {
  svg: document.getElementById("lineage-svg"),
  canvas: document.getElementById("canvas"),
  tooltip: document.getElementById("tooltip"),
  ttRel: document.getElementById("tt-rel"),
  ttRationale: document.getElementById("tt-rationale"),
  ttConf: document.getElementById("tt-conf"),
  filterBar: document.getElementById("relation-filter"),
  picker: document.getElementById("theme-picker"),
  meta: document.getElementById("theme-meta"),
  searchInput: document.getElementById("theme-search-input"),
  yearMin: document.getElementById("year-range-min"),
  yearMax: document.getElementById("year-range-max"),
  yearMinLabel: document.getElementById("year-range-min-label"),
  yearMaxLabel: document.getElementById("year-range-max-label"),
  minimap: document.getElementById("minimap"),
  minimapCanvas: document.getElementById("minimap-canvas"),
  exportSvg: document.getElementById("export-svg"),
  exportPng: document.getElementById("export-png"),
  xAxisMode: document.getElementById("x-axis-mode"),
  xAxisHint: document.getElementById("x-axis-hint"),
  xAxisLegendLeft: document.getElementById("x-axis-legend-left"),
  xAxisLegendRight: document.getElementById("x-axis-legend-right"),
  // On-demand theme submission UI.
  reqForm: document.getElementById("theme-request"),
  reqInput: document.getElementById("theme-request-input"),
  reqSubmit: document.getElementById("theme-request-submit"),
  reqHint: document.getElementById("theme-request-hint"),
  progress: document.getElementById("theme-progress"),
  progressTitle: document.getElementById("theme-progress-title"),
  progressElapsed: document.getElementById("theme-progress-elapsed"),
  progressBar: document.getElementById("theme-progress-bar"),
  progressSteps: document.getElementById("theme-progress-steps"),
  progressCancel: document.getElementById("theme-progress-cancel"),
  popover: document.getElementById("card-popover"),
  popVenue: document.getElementById("cp-venue"),
  popTitle: document.getElementById("cp-title"),
  popTldr: document.getElementById("cp-tldr"),
  popAuthors: document.getElementById("cp-authors"),
  popMeta: document.getElementById("cp-meta"),
};

// ---- Manifest / URL plumbing ----

async function loadManifest() {
  try {
    const res = await fetch("themes-manifest.json", { cache: "no-store" });
    if (!res.ok) return [];
    const data = await res.json();
    if (!Array.isArray(data)) return [];
    // Filter to entries with a valid slug — anything else can't be safely
    // spliced into a fetch URL anyway.
    return data.filter((e) => typeof e?.slug === "string" && SLUG_RE.test(e.slug));
  } catch {
    return [];
  }
}

async function loadThemeLineage(slug) {
  // Re-validate at the call site: even if state.currentSlug was set from a
  // trusted source, a future code path that bypasses init() must not be able
  // to splice an unsafe value into the fetch URL.
  if (!SLUG_RE.test(slug)) return null;
  // Page lives at /themes/index.html; per-slug JSONs at /themes/<slug>/lineage.json
  // — same directory level, so the fetch URL omits the "themes/" prefix.
  try {
    const res = await fetch(`${slug}/lineage.json`, { cache: "no-store" });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

function slugFromLocation() {
  const raw = new URLSearchParams(window.location.search).get("theme");
  return raw && SLUG_RE.test(raw) ? raw : null;
}

// #65: ?node=<paperId> permalink. paperIds are 40-char hex digests
// (S2 Corpus IDs); validate before using so a bad URL can't poison
// later DOM lookups via attribute selectors.
const NODE_ID_RE = /^[a-f0-9]{8,64}$/i;

// Strict arXiv id (mirrors deep.js ARXIV_RE) and DOI form. Used only
// when constructing the click-through paperUrl per node — hoisted to
// module scope so we don't re-compile the regexes once per render
// cycle in the inner draw loop.
const ARXIV_RE = /^\d{4}\.\d{4,5}(v\d+)?$/;
const DOI_RE = /^10\.\d{4,9}\/[A-Za-z0-9._;()/:-]+$/;
function focusNodeFromLocation() {
  const raw = new URLSearchParams(window.location.search).get("node");
  return raw && NODE_ID_RE.test(raw) ? raw : null;
}

function renderPicker() {
  if (!els.picker) return;
  if (state.manifest.length === 0) {
    els.picker.hidden = true;
    return;
  }
  els.picker.hidden = false;
  els.picker.innerHTML = state.manifest
    .map((e) => {
      const label = `${e.theme} — ${e.paper_count} papers`;
      const selected = e.slug === state.currentSlug ? " selected" : "";
      return `<option value="${escapeHtml(e.slug)}"${selected}>${escapeHtml(label)}</option>`;
    })
    .join("");
}

// Split from renderPicker() so re-rendering options doesn't accumulate
// duplicate change listeners. Called exactly once from init().
function bindPicker() {
  if (!els.picker) return;
  els.picker.addEventListener("change", () => {
    const slug = els.picker.value;
    // Second checkpoint: re-validate before updating the URL. Defends
    // against a (theoretical) injected option value bypassing the
    // manifest filter in renderPicker().
    if (!SLUG_RE.test(slug)) return;
    const url = new URL(window.location.href);
    url.searchParams.set("theme", slug);
    window.location.href = url.toString();
  });
}

function renderHeader() {
  if (!els.meta) return;
  const entry = state.manifest.find((e) => e.slug === state.currentSlug);
  const meta = state.data?.meta || {};
  const yearRange = entry?.year_range
    ? `${entry.year_range[0]}–${entry.year_range[1]}`
    : "—";
  const count = entry?.paper_count ?? state.data?.nodes?.length ?? 0;
  const keywords = Array.isArray(meta.keywords) ? meta.keywords : [];
  els.meta.innerHTML = `
    <span class="theme-meta__pill">📅 ${escapeHtml(yearRange)}</span>
    <span class="theme-meta__pill">📄 ${count} papers</span>
    ${keywords.length
      ? `<span class="theme-meta__pill" title="${escapeHtml(keywords.join(", "))}">🔍 ${keywords.length} keywords</span>`
      : ""}
  `;
  document.title = `${meta.theme || "Theme"} — Theme Lineage — PaperPilot`;
}

// SECURITY: ``safeHtml`` is interpolated raw into the DOM. Every caller
// in this file passes a static template literal or pre-escapes via
// ``escapeHtml(...)``. Never feed untrusted strings (URL params, fetch
// responses, user input) here without escaping first — that would be a
// stored / reflected XSS sink.
function showErrorHtml(safeHtml) {
  els.canvas.insertAdjacentHTML(
    "beforeend",
    `<div class="empty-state">${safeHtml}</div>`,
  );
}

// ---- On-demand theme submission ---------------------------------------
//
// Posts the user-typed theme to /api/themes (CF Worker). The Worker
// validates, dedupes against the manifest, rate-limits per IP, and
// dispatches a GitHub Actions workflow that runs build_theme_lineage.py
// and commits the result to develop. We then poll themes-manifest.json
// until the new slug appears (Cloudflare Pages auto-deploys on push)
// and redirect to ?theme=<slug>.

const REQUEST_PATTERN = /^[A-Za-z0-9 _-]{2,80}$/;
const POLL_INTERVAL_MS = 5000;
const POLL_TIMEOUT_MS = 6 * 60 * 1000;        // 6 min hard cap
const ESTIMATED_DURATION_MS = 3.5 * 60 * 1000; // tuned to typical run time

const PROGRESS_STEPS = ["dispatch", "queue", "generate", "commit", "ready"];

let progressState = null;

function bindThemeRequest() {
  if (!els.reqForm) return;
  els.reqForm.addEventListener("submit", (e) => {
    e.preventDefault();
    submitTheme().catch((err) => {
      console.error("[theme-request] submit failed:", err);
      showRequestError("予期しないエラーが発生しました。再試行してください。");
    });
  });
  if (els.progressCancel) {
    els.progressCancel.addEventListener("click", cancelProgress);
  }
}

function showRequestError(message) {
  if (!els.reqHint) return;
  els.reqHint.textContent = message;
  els.reqHint.classList.add("theme-request__hint--error");
  // Reset error styling after a few seconds so the form stops looking
  // like it's permanently broken.
  setTimeout(() => {
    if (els.reqHint) {
      els.reqHint.classList.remove("theme-request__hint--error");
      els.reqHint.textContent = "2〜80 文字 / [A-Za-z0-9 _-] / 5回/時まで";
    }
  }, 6000);
}

async function submitTheme() {
  const raw = (els.reqInput?.value || "").trim();
  if (!REQUEST_PATTERN.test(raw)) {
    showRequestError("テーマは 2〜80 文字、[A-Za-z0-9 _-] のみ使用できます。");
    return;
  }
  els.reqSubmit.disabled = true;
  els.reqInput.disabled = true;

  // POST to the Worker. credentials: same-origin keeps the cookie /
  // session story unchanged (we don't use either, but be explicit).
  let resp;
  try {
    resp = await fetch("/api/themes", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ theme: raw }),
      credentials: "same-origin",
    });
  } catch (e) {
    showRequestError("送信できませんでした。ネットワーク接続を確認してください。");
    els.reqSubmit.disabled = false;
    els.reqInput.disabled = false;
    return;
  }
  let data;
  try {
    data = await resp.json();
  } catch {
    data = { ok: false, status: "error", message: "invalid response" };
  }

  if (!data.ok && data.status === "rate_limited") {
    showRequestError("レート制限に達しました (5回/時)。1 時間後にお試しください。");
    els.reqSubmit.disabled = false;
    els.reqInput.disabled = false;
    return;
  }
  if (!data.ok && data.status === "invalid") {
    showRequestError(data.message || "入力が無効です。");
    els.reqSubmit.disabled = false;
    els.reqInput.disabled = false;
    return;
  }
  if (!data.ok) {
    showRequestError(data.message || "サーバ側でエラーが発生しました。");
    els.reqSubmit.disabled = false;
    els.reqInput.disabled = false;
    return;
  }

  if (data.status === "exists" && data.slug) {
    // Slug already published — jump straight to it. SLUG_RE re-checked
    // because the Worker's response could in theory be tampered with at
    // the network layer.
    if (SLUG_RE.test(data.slug)) {
      window.location.href = `?theme=${encodeURIComponent(data.slug)}`;
    }
    return;
  }

  if (data.status === "queued" && data.slug && SLUG_RE.test(data.slug)) {
    startProgress(data.slug, raw);
    return;
  }

  showRequestError("不明な状態が返されました。");
  els.reqSubmit.disabled = false;
  els.reqInput.disabled = false;
}

function startProgress(slug, themeLabel) {
  els.progress.hidden = false;
  if (els.progressTitle) els.progressTitle.textContent = `「${themeLabel}」を生成中...`;
  setProgressStep("dispatch");
  progressState = {
    slug,
    startedAt: Date.now(),
    cancelled: false,
    timer: null,
  };
  // Step transitions are time-based estimates. We shift "queue" → "generate"
  // → "commit" on a schedule because the Worker can't tell us the live
  // workflow status without a second API hop. This stays accurate enough
  // for the user-facing "what's happening now" because the median run
  // time is fairly stable.
  setTimeout(() => maybeAdvance("queue"), 5_000);
  setTimeout(() => maybeAdvance("generate"), 30_000);
  setTimeout(() => maybeAdvance("commit"), 150_000);
  pollForCompletion(slug);
  progressState.timer = setInterval(updateElapsed, 1000);
  updateElapsed();
}

function maybeAdvance(step) {
  if (!progressState || progressState.cancelled) return;
  setProgressStep(step);
}

function setProgressStep(step) {
  if (!els.progressSteps) return;
  const idx = PROGRESS_STEPS.indexOf(step);
  for (const li of els.progressSteps.querySelectorAll("li[data-step]")) {
    const liIdx = PROGRESS_STEPS.indexOf(li.dataset.step);
    li.classList.toggle("theme-progress__step--done", liIdx < idx);
    li.classList.toggle("theme-progress__step--current", liIdx === idx);
    li.classList.toggle("theme-progress__step--pending", liIdx > idx);
  }
  if (els.progressBar) {
    const pct = Math.min(100, (idx / (PROGRESS_STEPS.length - 1)) * 100);
    els.progressBar.style.width = `${pct}%`;
  }
}

function updateElapsed() {
  if (!progressState || !els.progressElapsed) return;
  const elapsed = Date.now() - progressState.startedAt;
  const m = Math.floor(elapsed / 60_000);
  const s = Math.floor((elapsed % 60_000) / 1000);
  els.progressElapsed.textContent = `経過 ${m}:${String(s).padStart(2, "0")}`;
}

async function pollForCompletion(slug) {
  const startedAt = Date.now();
  while (progressState && !progressState.cancelled) {
    if (Date.now() - startedAt > POLL_TIMEOUT_MS) {
      showRequestError("生成がタイムアウトしました。後ほど再試行してください。");
      cancelProgress();
      return;
    }
    try {
      // cache: no-store guarantees we don't keep seeing a stale manifest
      // from the CDN. Even right after a CF Pages deploy the manifest
      // can still be cached at the edge for ~30s.
      const r = await fetch("themes-manifest.json", { cache: "no-store" });
      if (r.ok) {
        const data = await r.json();
        if (Array.isArray(data) && data.some((e) => e?.slug === slug)) {
          setProgressStep("ready");
          // Tiny pause so the user sees the green "完了" tick.
          setTimeout(() => {
            window.location.href = `?theme=${encodeURIComponent(slug)}`;
          }, 800);
          return;
        }
      }
    } catch {
      // Transient network error — keep polling. The hard cap above will
      // bail if the failure persists.
    }
    await new Promise((r) => setTimeout(r, POLL_INTERVAL_MS));
  }
}

function cancelProgress() {
  if (progressState) {
    progressState.cancelled = true;
    if (progressState.timer) clearInterval(progressState.timer);
  }
  if (els.progress) els.progress.hidden = true;
  if (els.reqSubmit) els.reqSubmit.disabled = false;
  if (els.reqInput) els.reqInput.disabled = false;
}

async function init() {
  els.canvas.insertAdjacentHTML("beforeend", `<p class="empty-state" id="loading-msg">テーマを読み込み中...</p>`);

  // Bind the on-demand submission form FIRST so it stays usable even
  // when the manifest is empty (first-time visitor) or when the slug
  // they asked for can't be loaded.
  bindThemeRequest();

  state.manifest = await loadManifest();
  if (state.manifest.length === 0) {
    document.getElementById("loading-msg")?.remove();
    showErrorHtml(`
      <p>テーマがまだ生成されていません。</p>
      <p>上のフォームに研究テーマを入力すると自動生成できます。例: <em>Vision Transformer</em>, <em>Diffusion Model</em></p>
    `);
    return;
  }

  // Pick the requested slug if it's known; otherwise fall back to the
  // alphabetically first manifest entry.
  const requested = slugFromLocation();
  const known = new Set(state.manifest.map((e) => e.slug));
  state.currentSlug = (requested && known.has(requested))
    ? requested
    : state.manifest[0].slug;

  state.data = await loadThemeLineage(state.currentSlug);
  document.getElementById("loading-msg")?.remove();

  if (!state.data) {
    renderPicker();
    bindPicker();
    showErrorHtml(`<p><code>${escapeHtml(state.currentSlug)}</code> の lineage.json が読み込めません。</p>`);
    return;
  }

  if (!Array.isArray(state.data.nodes) || state.data.nodes.length === 0) {
    renderPicker();
    bindPicker();
    renderHeader();
    showErrorHtml(`<p>このテーマにはノードがありません（検索結果が空だった可能性あり）。</p>`);
    return;
  }

  renderPicker();
  bindPicker();
  renderHeader();
  renderFilterChips();
  bindFilterBar();
  bindXAxisMode();
  bindSearch();
  setupYearRange();
  bindYearRange();
  bindExport();
  render();

  // #65: if the URL carried a ?node=, scroll to it and highlight after
  // the SVG has had a frame to paint. Two requestAnimationFrame ticks
  // give the foreignObjects time to lay out before we measure.
  const requestedNode = focusNodeFromLocation();
  if (requestedNode) {
    requestAnimationFrame(() => requestAnimationFrame(() =>
      focusNode(requestedNode)
    ));
  }
}

// #82: PNG / SVG export — bake the live SVG (with foreignObject HTML
// inside) into a stand-alone document and trigger a browser download.
// CSS is inlined so the exported image renders identically off-line.
function bindExport() {
  // Wrap async export() so a rejected promise (image load fail, etc.)
  // surfaces in the console instead of an unhandled rejection.
  const safe = (kind) => () => {
    exportImage(kind).catch((err) => {
      console.error("export failed:", err);
    });
  };
  if (els.exportSvg) els.exportSvg.addEventListener("click", safe("svg"));
  if (els.exportPng) els.exportPng.addEventListener("click", safe("png"));
}

async function buildSelfContainedSvg() {
  const svg = els.svg;
  const clone = svg.cloneNode(true);
  // Inline computed styles for every element so the SVG renders the
  // same with no external stylesheet. Walk the clone and the live tree
  // in lockstep so we copy the styles browsers actually used.
  const cssText = await collectInlineCss();
  const defs = clone.querySelector("defs") || (() => {
    const d = document.createElementNS(SVG_NS, "defs");
    clone.insertBefore(d, clone.firstChild);
    return d;
  })();
  const style = document.createElementNS(SVG_NS, "style");
  style.textContent = cssText;
  defs.appendChild(style);
  // Ensure xmlns on the root.
  clone.setAttribute("xmlns", SVG_NS);
  clone.setAttribute("xmlns:xhtml", XHTML_NS);
  return new XMLSerializer().serializeToString(clone);
}

async function collectInlineCss() {
  // Only inline CSS from the application's own stylesheet so a browser
  // extension or a third-party script that injects rules at runtime
  // can't ride along into the exported file (security review #82).
  const parts = [];
  for (const sheet of document.styleSheets) {
    const href = sheet.href || "";
    // Match the deployed style.css path (cache-bust query allowed).
    if (!href.includes("/assets/style.css")) continue;
    try {
      for (const rule of sheet.cssRules) {
        parts.push(rule.cssText);
      }
    } catch {
      /* skip — same-origin should never throw, but be defensive */
    }
  }
  return parts.join("\n");
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  // Revoke immediately after the synchronous click — the download
  // manager already holds a reference to the blob (review #82 HIGH:
  // the previous 1-second timer could revoke before slow networks
  // started or after page hide stalled the timer).
  URL.revokeObjectURL(url);
}

async function exportImage(kind) {
  const xml = await buildSelfContainedSvg();
  const date = new Date().toISOString().slice(0, 10);
  const slug = state.currentSlug || "theme";
  const base = `${slug}-lineage-${date}`;
  if (kind === "svg") {
    const blob = new Blob([`<?xml version="1.0" encoding="UTF-8"?>\n${xml}`],
      { type: "image/svg+xml;charset=utf-8" });
    downloadBlob(blob, `${base}.svg`);
    return;
  }
  // PNG: rasterize via canvas. SVGs containing <foreignObject> taint
  // the canvas (browsers refuse toBlob with SecurityError) — detect
  // that and fall back to the SVG download with a user-visible message
  // so the click never silently produces nothing (review #82 HIGH).
  const w = parseFloat(els.svg.getAttribute("width")) || 1;
  const h = parseFloat(els.svg.getAttribute("height")) || 1;
  const cap = 8000;
  const scale = Math.min(2, cap / Math.max(w, h));
  const cw = Math.round(w * scale);
  const ch = Math.round(h * scale);
  const canvas = document.createElement("canvas");
  canvas.width = cw;
  canvas.height = ch;
  const ctx = canvas.getContext("2d");
  // Pull the page background colour from a CSS custom property so the
  // export tracks any future palette change instead of a hardcoded hex.
  const bg = getComputedStyle(document.documentElement)
    .getPropertyValue("--color-bg").trim() || "#fdfaf3";
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, cw, ch);
  const img = new Image();
  const svgUrl = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(xml);
  try {
    await new Promise((resolve, reject) => {
      img.onload = resolve;
      img.onerror = () => reject(new Error("SVG image load failed"));
      img.src = svgUrl;
    });
    ctx.drawImage(img, 0, 0, cw, ch);
  } catch (err) {
    // Image failed to load → SVG download fallback.
    console.warn("PNG export failed:", err);
    return exportImage("svg");
  }
  await new Promise((resolve) => {
    canvas.toBlob((blob) => {
      if (blob) {
        downloadBlob(blob, `${base}.png`);
      } else {
        // toBlob === null when the canvas is tainted (foreignObject case).
        console.warn("PNG export blob came back null — falling back to SVG.");
        exportImage("svg");
      }
      // Release the canvas backing store immediately so a 8000×8000
      // export doesn't sit at ~256 MB until the next GC tick.
      canvas.width = canvas.height = 0;
      resolve();
    }, "image/png");
  });
}

// #65: scroll target node into view + reuse the hover-highlight pipeline
// to draw attention to it and its incident edges.
function focusNode(nodeId) {
  const fo = document.querySelector(`foreignObject[data-node-id="${nodeId}"]`);
  if (!fo) return; // node not in this theme — silently noop
  const svgX = parseFloat(fo.getAttribute("x")) || 0;
  const svgY = parseFloat(fo.getAttribute("y")) || 0;
  // foreignObject coords are in the SVG viewport — convert to page coords.
  const svg = els.svg;
  const ctm = svg.getScreenCTM();
  if (ctm) {
    const pageX = svgX * ctm.a + svgY * ctm.c + ctm.e;
    const pageY = svgX * ctm.b + svgY * ctm.d + ctm.f;
    const targetX = pageX + window.scrollX - window.innerWidth / 2 + NODE_W / 2;
    const targetY = pageY + window.scrollY - window.innerHeight / 2 + NODE_H / 2;
    window.scrollTo({ left: Math.max(0, targetX), top: Math.max(0, targetY), behavior: "smooth" });
  }
  highlightNode(nodeId);
}

// #62: derive min/max from the loaded data and seed the two range inputs.
// Idempotent — safe to call again on theme switch.
function setupYearRange() {
  if (!els.yearMin || !els.yearMax) return;
  const years = (state.data?.nodes || [])
    .map((n) => n.year)
    .filter((y) => typeof y === "number");
  if (years.length === 0) {
    document.getElementById("year-range")?.style.setProperty("display", "none");
    return;
  }
  const minY = Math.min(...years);
  const maxY = Math.max(...years);
  for (const inp of [els.yearMin, els.yearMax]) {
    inp.min = String(minY);
    inp.max = String(maxY);
    inp.step = "1";
  }
  els.yearMin.value = String(minY);
  els.yearMax.value = String(maxY);
  state.yearRange.min = minY;
  state.yearRange.max = maxY;
  if (els.yearMinLabel) els.yearMinLabel.textContent = String(minY);
  if (els.yearMaxLabel) els.yearMaxLabel.textContent = String(maxY);
}

function bindYearRange() {
  if (!els.yearMin || !els.yearMax) return;
  let pending = null;
  const onInput = () => {
    let lo = Number(els.yearMin.value);
    let hi = Number(els.yearMax.value);
    // Keep handles ordered — if the user drags past, swap.
    if (lo > hi) [lo, hi] = [hi, lo];
    state.yearRange.min = lo;
    state.yearRange.max = hi;
    if (els.yearMinLabel) els.yearMinLabel.textContent = String(lo);
    if (els.yearMaxLabel) els.yearMaxLabel.textContent = String(hi);
    clearTimeout(pending);
    pending = setTimeout(render, 80);
  };
  els.yearMin.addEventListener("input", onInput);
  els.yearMax.addEventListener("input", onInput);
}


// #61: search-box wiring. Debounced re-render so each keystroke doesn't
// rebuild the whole SVG.
function bindSearch() {
  if (!els.searchInput) return;
  let pending = null;
  els.searchInput.addEventListener("input", () => {
    state.searchQuery = els.searchInput.value || "";
    clearTimeout(pending);
    pending = setTimeout(render, 120);
  });
}

function renderFilterChips() {
  if (!els.filterBar) return;
  const labels = {
    supersedes: "Supersedes", successor: "Successor", extends: "Extends",
    ablation: "Ablation", baseline_only: "Baseline", contrasts: "Contrasts",
  };
  // Count edges per relation so the chip can show the budget at a glance —
  // big asymmetries (e.g. "Extends 64 / Successor 2") nudge the user to
  // toggle filters rather than scroll through a wall of one type.
  const counts = {};
  for (const e of state.data?.edges || []) {
    counts[e.rel] = (counts[e.rel] || 0) + 1;
  }
  // innerHTML only — listener is bound once via bindFilterBar() to avoid
  // accumulating duplicates if this is ever called on re-render.
  els.filterBar.innerHTML = ALL_RELATIONS.map((r) => {
    const on = state.visibleRelations.has(r);
    const dotKind = r === "baseline_only" ? "baseline" : r;
    const count = counts[r] || 0;
    return `<button class="chip chip--rel" data-rel="${r}" aria-pressed="${on}">
      <span class="chip__dot chip__dot--${dotKind}"></span>
      ${labels[r]}
      <span class="chip__count">${count}</span>
    </button>`;
  }).join("");
}

// Render the X-axis pill button group from X_AXIS_MODES + X_AXIS_BUTTON
// and wire the click delegation. Called once from init() — splitting
// from re-renders keeps the listener from accumulating if init() ever
// re-runs.
function bindXAxisMode() {
  if (!els.xAxisMode) return;
  // Build the buttons. The header label inside the group element is
  // preserved (HTML-side static node) so we only append after it.
  const labelEl = els.xAxisMode.querySelector(".x-axis-group__label");
  els.xAxisMode.innerHTML = "";
  if (labelEl) els.xAxisMode.appendChild(labelEl);
  for (const mode of X_AXIS_MODES) {
    const meta = X_AXIS_BUTTON[mode];
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "chip chip--xaxis";
    btn.dataset.xaxis = mode;
    btn.title = meta.title;
    btn.setAttribute("aria-pressed", String(mode === state.xAxisMode));
    // textContent (not innerHTML) — meta is a const map but treat it as
    // untrusted to keep XSS-by-future-edit out of reach.
    btn.textContent = `${meta.icon} ${meta.label}`;
    els.xAxisMode.appendChild(btn);
  }
  // Click delegation on the group keeps a single listener regardless of
  // how many buttons get rendered.
  els.xAxisMode.addEventListener("click", (e) => {
    const btn = e.target.closest(".chip[data-xaxis]");
    if (!btn) return;
    const next = btn.dataset.xaxis;
    // Allowlist guard: data-xaxis comes from DOM and could be tampered
    // with. Reject anything outside the known mode set.
    if (!X_AXIS_MODES.includes(next)) return;
    if (next === state.xAxisMode) return;
    state.xAxisMode = next;
    // Re-paint pressed state on every button so screen readers see the
    // update synchronously, before the (potentially expensive) render().
    for (const b of els.xAxisMode.querySelectorAll(".chip[data-xaxis]")) {
      b.setAttribute("aria-pressed", String(b.dataset.xaxis === state.xAxisMode));
    }
    savePrefs();
    render();
  });
}

// Refresh both the footer hint and the canvas-top legend so the on-
// screen description matches the current X-axis encoding. Called from
// render() (after the layout is applied) so the legend never claims an
// encoding that isn't actually rendered.
function updateXAxisHint() {
  // textContent (not innerHTML) — the hint maps are static consts, but
  // treat them as untrusted to keep XSS-by-future-edit out of reach.
  if (els.xAxisHint) {
    els.xAxisHint.textContent = X_AXIS_HINT[state.xAxisMode] || X_AXIS_HINT[DEFAULT_X_AXIS_MODE];
  }
  const legend = X_AXIS_LEGEND[state.xAxisMode] || X_AXIS_LEGEND[DEFAULT_X_AXIS_MODE];
  if (els.xAxisLegendLeft) els.xAxisLegendLeft.textContent = legend.left;
  if (els.xAxisLegendRight) els.xAxisLegendRight.textContent = legend.right;
}

// Split from renderFilterChips() so re-rendering chips never accumulates
// duplicate listeners. Called once from init().
function bindFilterBar() {
  if (!els.filterBar) return;
  els.filterBar.addEventListener("click", (e) => {
    const btn = e.target.closest(".chip[data-rel]");
    if (!btn) return;
    const rel = btn.dataset.rel;
    // Allowlist guard: data-rel comes from DOM and could be tampered with
    // by extensions or future edits — only the known relation enum is honoured.
    if (!ALL_RELATIONS.includes(rel)) return;
    if (state.visibleRelations.has(rel)) state.visibleRelations.delete(rel);
    else state.visibleRelations.add(rel);
    btn.setAttribute("aria-pressed", state.visibleRelations.has(rel));
    savePrefs();
    render();
  });
}

// ---- Layout ----

// Map a node's venue_tier string to a sortable bucket id used by both
// the venue-mode X-axis and the venue-mode card stripe CSS.
//   "A+" / "aplus"   → 1 (top-tier conferences: NeurIPS, ICML, ICLR…)
//   "A"  / "a"       → 2 (good conferences)
//   "preprint" / "" / null → 3 (arXiv-only / unknown)
//   number 1|2|3     → pass through (forward-compat for if the pipeline
//                      ever emits numeric tiers)
//   anything else    → 99 (sorts last; signals "unknown shape")
function venueTierBucket(tier) {
  if (typeof tier === "number") {
    if (tier >= 1 && tier <= 3) return tier;
    return 99;
  }
  if (typeof tier !== "string") return 99;
  const t = tier.trim().toLowerCase();
  if (t === "a+" || t === "aplus") return 1;
  if (t === "a") return 2;
  if (t === "preprint" || t === "") return 3;
  return 99;
}

// Score a node for the given X-axis mode. Lower score = further left.
// All scores are returned as plain numbers so the caller can sort with a
// stable comparator. NaN / null are coerced to a large positive value so
// missing data sorts to the right edge instead of breaking the comparator.
//
// The "rank" mode is implemented by the caller (sort by citation_count
// desc) and not via this helper, because rank doesn't need a per-node
// score — it's a pure sort order.
function scoreForMode(node, mode, ctx) {
  switch (mode) {
    case "citation_log": {
      // Negate so higher citations sort first (left).
      const c = typeof node.citation_count === "number" ? node.citation_count : 0;
      return -Math.log10(c + 1);
    }
    case "genealogy": {
      // Average X of parents that have already been positioned. Genealogy
      // scores are pixel coordinates (positive numbers in the hundreds–
      // thousands), so orphans must use a sentinel on the *same* scale or
      // they pollute the sort. Number.POSITIVE_INFINITY pushes parentless
      // nodes to the right edge of their year row, with citation desc as
      // the tie-break inside the orphan group (handled by the caller).
      const parents = ctx.parentsById.get(node.id);
      if (!parents || parents.size === 0) return Number.POSITIVE_INFINITY;
      let sum = 0, n = 0;
      for (const pid of parents) {
        const px = ctx.placedX.get(pid);
        if (typeof px === "number") { sum += px; n++; }
      }
      if (n === 0) return Number.POSITIVE_INFINITY;
      return sum / n;
    }
    case "centrality": {
      // PageRank — high rank = central hub = left edge.
      const r = ctx.pagerank.get(node.id) || 0;
      return -r;
    }
    case "venue": {
      // venue_tier comes from build_*_lineage.py as a STRING — "A+" /
      // "A" / "preprint" — not a numeric grade. Map to a sortable
      // bucket (lower = further left). Tie-break with citation desc so
      // a single tier reads in citation order.
      const tier = venueTierBucket(node.venue_tier);
      const c = typeof node.citation_count === "number" ? node.citation_count : 0;
      return tier * 1e9 - c;
    }
    case "novelty": {
      // Edges incident to this node, grouped by outgoing relation kind.
      // - supersedes outbound = "displaces ancestors" → very disruptive (left)
      // - successor / extends outbound = "builds on ancestors" → incremental (right)
      // Score is (incremental - disruptive) so larger = further right.
      // Nodes with no edges fall back to citation rank.
      const edges = ctx.edgesByNode.get(node.id) || [];
      let disrupt = 0, incremental = 0;
      for (const e of edges) {
        if (e.dst !== node.id) continue; // only incoming edges describe how this paper relates to its ancestors
        if (e.rel === "supersedes" || e.rel === "contrasts") disrupt += 1;
        else if (e.rel === "successor" || e.rel === "extends" || e.rel === "ablation") incremental += 1;
      }
      if (disrupt === 0 && incremental === 0) {
        const c = typeof node.citation_count === "number" ? node.citation_count : 0;
        return -c * 1e-6; // tiny weight so genuine novelty signals dominate
      }
      return incremental - disrupt;
    }
    default: {
      // Unknown mode — fall back to citation rank.
      const c = typeof node.citation_count === "number" ? node.citation_count : 0;
      return -c;
    }
  }
}

// Compute a damped PageRank over the lineage edges. Edges are treated as
// child→parent ("descendants vote for the ancestor that influenced them")
// because the lineage convention stores src=parent, dst=child — naïve
// PageRank on that orientation would rank leaf papers highest, which is
// the opposite of what "central / influential" means in a research tree.
// Reversing the edge means a paper with many descendants gathers rank
// from them, surfacing seed papers and method-defining ancestors.
//
// 20 iterations is plenty for the graph sizes we deal with (typically
// well under 200 nodes per theme); we don't need numeric stability
// beyond visual ordering.
function computePagerank(nodes, edges, { damping = 0.85, iterations = 20 } = {}) {
  const ids = nodes.map((n) => n.id);
  const N = ids.length;
  if (N === 0) return new Map();
  const rank = new Map(ids.map((id) => [id, 1 / N]));
  const out = new Map(ids.map((id) => [id, []]));
  const outDeg = new Map(ids.map((id) => [id, 0]));
  // Drop stray edges before iterating so a stray endpoint can never make
  // an in-graph node falsely look dangling (its other valid edges would
  // still register, but we'd misrepresent its out-degree). build_theme_
  // lineage.py emits closed graphs so this is mostly defensive, but it
  // also lets the function be safely reused from other contexts.
  const validEdges = (edges || []).filter((e) => out.has(e.dst) && rank.has(e.src));
  for (const e of validEdges) {
    // Reverse direction: a child's vote flows to its parent.
    out.get(e.dst).push(e.src);
    outDeg.set(e.dst, outDeg.get(e.dst) + 1);
  }
  const base = (1 - damping) / N;
  for (let iter = 0; iter < iterations; iter++) {
    const next = new Map(ids.map((id) => [id, base]));
    let dangling = 0;
    for (const id of ids) {
      if (outDeg.get(id) === 0) dangling += rank.get(id);
    }
    const danglingShare = damping * dangling / N;
    for (const id of ids) next.set(id, next.get(id) + danglingShare);
    for (const id of ids) {
      const r = rank.get(id);
      const targets = out.get(id);
      if (targets.length === 0) continue;
      const share = damping * r / targets.length;
      for (const t of targets) next.set(t, next.get(t) + share);
    }
    for (const id of ids) rank.set(id, next.get(id));
  }
  return rank;
}

// Build helper indexes used by scoreForMode().
function buildLayoutContext(nodes, edges) {
  const parentsById = new Map(nodes.map((n) => [n.id, new Set()]));
  const edgesByNode = new Map(nodes.map((n) => [n.id, []]));
  for (const e of edges || []) {
    if (parentsById.has(e.dst)) parentsById.get(e.dst).add(e.src);
    if (edgesByNode.has(e.dst)) edgesByNode.get(e.dst).push(e);
    if (edgesByNode.has(e.src)) edgesByNode.get(e.src).push(e);
  }
  const pagerank = computePagerank(nodes, edges || []);
  return { parentsById, edgesByNode, pagerank, placedX: new Map() };
}

function layoutChronological(nodes, edges, mode = DEFAULT_X_AXIS_MODE) {
  if (!X_AXIS_MODES.includes(mode)) mode = DEFAULT_X_AXIS_MODE;

  // Bucket nodes by year. Unknown-year nodes go into a final synthetic
  // bucket so the chronological viewer never silently drops them.
  const byYear = new Map();
  for (const n of nodes) {
    const key = typeof n.year === "number" ? n.year : UNKNOWN_YEAR;
    if (!byYear.has(key)) byYear.set(key, []);
    byYear.get(key).push(n);
  }

  // Sort known years ascending; unknown bucket appended last. Genealogy
  // mode depends on this order so parents (older years) are placed before
  // children (newer years) — placedX would be empty otherwise.
  const years = [...byYear.keys()].filter((y) => y !== UNKNOWN_YEAR).sort((a, b) => a - b);
  if (byYear.has(UNKNOWN_YEAR)) years.push(UNKNOWN_YEAR);

  const ctx = buildLayoutContext(nodes, edges);

  // For non-genealogy modes we can sort each year row up-front because
  // scores don't depend on placement order. For genealogy we sort row by
  // row inside the placement loop so each row sees the freshly-placed
  // parents from earlier years.
  if (mode !== "genealogy") {
    for (const y of years) {
      const row = byYear.get(y);
      if (mode === "rank") {
        row.sort((a, b) => (b.citation_count || 0) - (a.citation_count || 0));
      } else {
        row.sort((a, b) => scoreForMode(a, mode, ctx) - scoreForMode(b, mode, ctx));
      }
    }
  }

  const maxRow = Math.max(0, ...[...byYear.values()].map((v) => v.length));
  const rowSpanW = maxRow * (NODE_W + SIBLING_GAP);
  const totalW = YEAR_LABEL_W + rowSpanW + PADDING;
  const totalH = PADDING + years.length * (NODE_H + ROW_GAP) + PADDING;

  const positioned = [];
  const yearLabels = [];

  // Left-align rows (was center-aligned): with a wide max row, sparse
  // years drift to the middle of a 6000+ px grid and disappear off
  // typical viewports. Anchoring everything to the same left x keeps
  // older years in view without a horizontal scroll.
  years.forEach((year, rowIdx) => {
    const row = byYear.get(year);
    if (mode === "genealogy") {
      // Sort now so each row sees the placedX of all earlier years.
      // Citation desc is the tiebreaker so orphan rows (no parents yet
      // placed) still feel ordered by impact.
      row.sort((a, b) => {
        const sa = scoreForMode(a, mode, ctx);
        const sb = scoreForMode(b, mode, ctx);
        if (sa !== sb) return sa - sb;
        return (b.citation_count || 0) - (a.citation_count || 0);
      });
    }
    const xStart = YEAR_LABEL_W + PADDING / 2;
    const y = PADDING + rowIdx * (NODE_H + ROW_GAP);
    // #64: classify the year row so the axis can highlight 5- and 10-
    // year boundaries. decade-major (year % 10 == 0) > decade (% 5 == 0)
    // > regular > unknown.
    let importance = "regular";
    if (year !== UNKNOWN_YEAR) {
      if (year % 10 === 0) importance = "decade-major";
      else if (year % 5 === 0) importance = "decade";
    }
    yearLabels.push({
      label: year === UNKNOWN_YEAR ? "Unknown" : String(year),
      y: y + NODE_H / 2,
      isUnknown: year === UNKNOWN_YEAR,
      importance,
    });
    row.forEach((n, i) => {
      const x = xStart + i * (NODE_W + SIBLING_GAP);
      positioned.push({ ...n, _x: x, _y: y });
      ctx.placedX.set(n.id, x);
    });
  });

  return { positioned, yearLabels, totalW, totalH };
}

// Per-mode card metadata. Returns a Map<id, { kind, value }> describing
// what visual treatment the card should pick up:
//   - venue:      kind="tier",       value=1|2|3|undefined (venue_tier)
//   - novelty:    kind="novelty",    value="disrupt"|"incremental"|"neutral"
//   - genealogy:  kind="lineage",    value=stable hash of seed-ancestor id
//                                    (CSS uses it as a hue offset)
//   - centrality: handled by existing hubSet logic; nothing extra here
// Other modes return an empty Map so cards stay in their default look.
function computeModeData(nodes, edges, mode) {
  const meta = new Map();
  if (mode === "venue") {
    // venue_tier is the STRING "A+" / "A" / "preprint" coming from
    // build_*_lineage.py — translate to a bucket id 1/2/3 the CSS rules
    // can target via [data-tier].
    for (const n of nodes) {
      const bucket = venueTierBucket(n.venue_tier);
      const value = bucket >= 1 && bucket <= 3 ? bucket : null;
      meta.set(n.id, { kind: "tier", value });
    }
    return meta;
  }
  if (mode === "novelty") {
    const incoming = new Map(nodes.map((n) => [n.id, []]));
    for (const e of edges) {
      if (incoming.has(e.dst)) incoming.get(e.dst).push(e.rel);
    }
    for (const n of nodes) {
      let disrupt = 0, incremental = 0;
      for (const rel of incoming.get(n.id) || []) {
        if (rel === "supersedes" || rel === "contrasts") disrupt += 1;
        else if (rel === "successor" || rel === "extends" || rel === "ablation") incremental += 1;
      }
      let v = "neutral";
      if (disrupt > incremental) v = "disrupt";
      else if (incremental > disrupt) v = "incremental";
      meta.set(n.id, { kind: "novelty", value: v });
    }
    return meta;
  }
  if (mode === "genealogy") {
    // Walk each node up to its furthest ancestor reachable via parent
    // edges; the ancestor id becomes the lineage bucket. Cards in the
    // same bucket get the same hue offset.
    const parents = new Map(nodes.map((n) => [n.id, []]));
    for (const e of edges) {
      if (parents.has(e.dst)) parents.get(e.dst).push(e.src);
    }
    const root = (id, seen = new Set()) => {
      if (seen.has(id)) return id;
      seen.add(id);
      const ps = parents.get(id) || [];
      if (ps.length === 0) return id;
      // Pick the parent with the smallest id deterministically so the
      // bucket assignment is stable across renders.
      const sorted = [...ps].sort();
      return root(sorted[0], seen);
    };
    for (const n of nodes) {
      const ancestor = root(n.id);
      // Hash the ancestor id to a 0..360 hue offset. Simple FNV-1a-ish
      // string hash — quality is fine for visual bucketing.
      let h = 0;
      for (let i = 0; i < ancestor.length; i++) h = (h * 31 + ancestor.charCodeAt(i)) & 0xffff;
      meta.set(n.id, { kind: "lineage", value: h % 360 });
    }
    return meta;
  }
  return meta;
}

// #83: rank nodes by total degree (in + out) and tag the top decile
// as "hubs" so the viewer can mark them with a 👑 badge + thick border.
// Returns a Set of node ids whose degree clears the 90th percentile.
function computeHubSet(nodes, edges) {
  const degree = new Map();
  for (const n of nodes) degree.set(n.id, 0);
  for (const e of edges) {
    if (degree.has(e.src)) degree.set(e.src, degree.get(e.src) + 1);
    if (degree.has(e.dst)) degree.set(e.dst, degree.get(e.dst) + 1);
  }
  const values = [...degree.values()].filter((d) => d > 0).sort((a, b) => a - b);
  // Need a meaningful sample to talk about percentiles at all. Bail
  // early on tiny graphs to avoid the small-N degeneracy where every
  // rank clamps to the maximum (review #83 MEDIUM).
  if (values.length < 5) return new Set();
  // 90th percentile (Math.ceil − 1 picks the value where 90% of obs
  // are ≤). Floor of 4 keeps the badge meaningful — sparse trees
  // shouldn't gild a node with only 2-3 connections.
  const idx = Math.min(Math.ceil(values.length * 0.9) - 1, values.length - 1);
  const threshold = Math.max(values[idx], 4);
  const hubs = new Set();
  for (const [id, d] of degree) if (d >= threshold) hubs.add(id);
  return hubs;
}

function render() {
  const { nodes, edges } = state.data;
  const visibleEdges = (edges || []).filter((e) => state.visibleRelations.has(e.rel));
  const layout = layoutChronological(nodes, edges || [], state.xAxisMode);
  updateXAxisHint();
  // #83: hub set computed against ALL edges (not just visible) so toggling
  // relation filters doesn't reshuffle which papers feel "important".
  state.hubSet = computeHubSet(nodes, edges || []);
  // Per-mode supplemental data passed through to drawSvg so card classes
  // can pick up signals that aren't visible in the layout itself
  // (disrupt/incremental ratio for novelty, parent-group color for
  // genealogy, etc.). Computed once per render so drawSvg stays a pure
  // consumer.
  state.modeData = computeModeData(nodes, edges || [], state.xAxisMode);
  // #61 / #62: combine search and year filters into a single match set
  // so drawSvg only needs one predicate. Filters are applied to nodes
  // (not the layout itself) so the chronological grid stays stable as
  // the user adjusts either control.
  const hasFilter = state.searchQuery
    || state.yearRange.min != null || state.yearRange.max != null;
  const matchSet = hasFilter
    ? new Set(
        nodes
          .filter((n) =>
            matchesSearch(n, state.searchQuery)
              && matchesYear(n, state.yearRange.min, state.yearRange.max),
          )
          .map((n) => n.id),
      )
    : null;
  drawSvg(layout, visibleEdges, matchSet);
}

// ---- SVG drawing ----

// FLIP-style animation between renders: snapshot old positions, rebuild
// SVG, set each surviving node's initial transform to its old slot, then
// in the next paint flip to the new slot — CSS transition does the rest.
// Edges intentionally don't animate; they redraw at the new positions and
// the 250ms node glide is short enough that the mismatch reads as
// "settling" rather than glitch.
function snapshotNodePositions() {
  const snap = new Map();
  if (!els.svg) return snap;
  for (const wrap of els.svg.querySelectorAll("g.node-wrap[data-node-id]")) {
    const id = wrap.dataset.nodeId;
    const tr = wrap.getAttribute("transform") || "";
    const m = tr.match(/translate\(\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*\)/);
    if (m) snap.set(id, { x: parseFloat(m[1]), y: parseFloat(m[2]) });
  }
  return snap;
}

function drawSvg({ positioned, yearLabels, totalW, totalH }, edges, matchSet) {
  // Capture before innerHTML="" wipes the DOM. Used by the FLIP block at
  // the end of this function to animate cards from their old slot to
  // their new one when only the X-axis mode (or filter) changed.
  const oldPositions = snapshotNodePositions();
  els.svg.innerHTML = "";
  if (positioned.length === 0) {
    els.canvas.querySelector(".empty-state")?.remove();
    els.canvas.insertAdjacentHTML("beforeend", `<p class="empty-state">表示できるノードがありません。</p>`);
    return;
  }
  // Stale empty-state from prior renders.
  els.canvas.querySelector(".empty-state")?.remove();

  els.svg.setAttribute("width", totalW);
  els.svg.setAttribute("height", totalH);
  els.svg.setAttribute("viewBox", `0 0 ${totalW} ${totalH}`);
  // Expose the active mode on the SVG element so CSS rules in style.css
  // can light up mode-specific visual treatments (tier stripe, novelty
  // tint, lineage hue) without per-card class soup.
  els.svg.dataset.xaxisMode = state.xAxisMode || DEFAULT_X_AXIS_MODE;

  // Defs: arrow markers per relation type.
  const defs = document.createElementNS(SVG_NS, "defs");
  for (const [key, color, kind] of [
    ["supersedes", "oklch(55% 0.14 75)", "filled"],
    ["successor",  "oklch(72% 0.13 80)", "filled"],
    ["extends",    "oklch(62% 0.14 145)", "filled"],
    ["ablation",   "oklch(60% 0.13 240)", "hollow"],
    ["baseline",   "oklch(60% 0.02 270)", "dot"],
    ["contrasts",  "oklch(58% 0.20 25)", "cross"],
  ]) {
    const m = document.createElementNS(SVG_NS, "marker");
    m.setAttribute("id", `arrow-theme-${key}`);
    m.setAttribute("viewBox", "0 0 10 10");
    m.setAttribute("refX", "9"); m.setAttribute("refY", "5");
    m.setAttribute("markerWidth", "7"); m.setAttribute("markerHeight", "7");
    m.setAttribute("orient", "auto-start-reverse");
    let shape;
    if (kind === "filled") {
      shape = document.createElementNS(SVG_NS, "path");
      shape.setAttribute("d", "M0,0 L10,5 L0,10 z");
      shape.setAttribute("fill", color);
    } else if (kind === "hollow") {
      shape = document.createElementNS(SVG_NS, "circle");
      shape.setAttribute("cx", "5"); shape.setAttribute("cy", "5"); shape.setAttribute("r", "3");
      shape.setAttribute("fill", "white"); shape.setAttribute("stroke", color); shape.setAttribute("stroke-width", "1.5");
    } else if (kind === "dot") {
      shape = document.createElementNS(SVG_NS, "circle");
      shape.setAttribute("cx", "5"); shape.setAttribute("cy", "5"); shape.setAttribute("r", "1.8");
      shape.setAttribute("fill", color);
    } else {
      shape = document.createElementNS(SVG_NS, "path");
      shape.setAttribute("d", "M0,0 L10,10 M10,0 L0,10");
      shape.setAttribute("stroke", color); shape.setAttribute("stroke-width", "1.8");
      shape.setAttribute("fill", "none");
    }
    m.appendChild(shape);
    defs.appendChild(m);
  }
  els.svg.appendChild(defs);

  // Year axis (left gutter): a short tick + label per row.
  const axis = document.createElementNS(SVG_NS, "g");
  axis.setAttribute("class", "chrono-axis");
  for (const { label, y, isUnknown, importance } of yearLabels) {
    const text = document.createElementNS(SVG_NS, "text");
    const cls = ["year-label"];
    if (isUnknown) cls.push("year-label--unknown");
    if (importance === "decade") cls.push("year-label--decade");
    if (importance === "decade-major") cls.push("year-label--decade-major");
    text.setAttribute("class", cls.join(" "));
    text.setAttribute("x", PADDING);
    text.setAttribute("y", y + 4);
    text.textContent = label;
    axis.appendChild(text);

    const tick = document.createElementNS(SVG_NS, "line");
    const tickCls = ["year-tick"];
    if (importance === "decade") tickCls.push("year-tick--decade");
    if (importance === "decade-major") tickCls.push("year-tick--decade-major");
    tick.setAttribute("class", tickCls.join(" "));
    tick.setAttribute("x1", YEAR_LABEL_W - 8);
    tick.setAttribute("y1", y);
    tick.setAttribute("x2", totalW - PADDING);
    tick.setAttribute("y2", y);
    axis.appendChild(tick);
  }
  els.svg.appendChild(axis);

  const posById = new Map(positioned.map((p) => [p.id, p]));

  // Edges (drawn before nodes so cards sit on top).
  const eg = document.createElementNS(SVG_NS, "g");
  eg.setAttribute("id", "edges");
  for (const e of edges) {
    const a = posById.get(e.src), b = posById.get(e.dst);
    if (!a || !b) continue;
    // #61: when a search filter is active, fade edges whose endpoints
    // are both outside the match set. Edges incident to a matched node
    // stay full-opacity so the user can see how a hit relates to its
    // neighbours.
    const edgeMatches = !matchSet || matchSet.has(e.src) || matchSet.has(e.dst);
    const ax = a._x + NODE_W / 2;
    const ay = a._y + NODE_H;
    const bx = b._x + NODE_W / 2;
    const by = b._y;
    const midY = (ay + by) / 2;
    const d = `M ${ax} ${ay} C ${ax} ${midY}, ${bx} ${midY}, ${bx} ${by}`;
    const mc = e.rel === "baseline_only" ? "baseline" : e.rel;
    const path = document.createElementNS(SVG_NS, "path");
    path.setAttribute("d", d);
    path.setAttribute("class", `edge edge--${mc}`);
    path.setAttribute("marker-end", `url(#arrow-theme-${mc})`);
    if (typeof e.conf === "number") path.style.strokeOpacity = String(0.5 + e.conf * 0.5);
    path.dataset.rel = e.rel;
    path.dataset.rationale = e.rationale || "";
    path.dataset.conf = e.conf ?? "";
    path.dataset.src = e.src;
    path.dataset.dst = e.dst;
    if (!edgeMatches) path.classList.add("edge--filtered");
    path.addEventListener("mouseenter", onEdgeHover);
    path.addEventListener("mousemove", onEdgeMove);
    path.addEventListener("mouseleave", onEdgeLeave);
    eg.appendChild(path);
  }
  els.svg.appendChild(eg);

  // Nodes
  const ng = document.createElementNS(SVG_NS, "g");
  ng.setAttribute("id", "nodes");
  for (const p of positioned) {
    // Each node is now wrapped in a <g class="node-wrap"> with a translate
    // transform; the FLIP block at the end of drawSvg uses this wrapper
    // to animate position changes between renders. The inner foreignObject
    // sits at (0, 0) so its CSS layout (the whole HTML card tree inside)
    // doesn't shift around when we re-translate the wrapper.
    const wrap = document.createElementNS(SVG_NS, "g");
    wrap.setAttribute("class", "node-wrap");
    wrap.setAttribute("transform", `translate(${p._x}, ${p._y})`);
    wrap.dataset.nodeId = p.id;
    const fo = document.createElementNS(SVG_NS, "foreignObject");
    fo.setAttribute("x", 0);
    fo.setAttribute("y", 0);
    fo.setAttribute("width", NODE_W);
    fo.setAttribute("height", NODE_H);
    // Let the ★ FOCUS badge (top: -10px) and the citation-heat box-shadow
    // halo render outside the foreignObject's NODE_W × NODE_H viewport.
    // Without this, those decorations get clipped at the card edge.
    // ROW_GAP=80 and SIBLING_GAP=28 leave plenty of clearance for the
    // ~10–22 px overhangs.
    fo.setAttribute("overflow", "visible");
    fo.style.overflow = "visible";
    fo.dataset.nodeId = p.id;
    const card = document.createElement("div");
    card.setAttribute("xmlns", XHTML_NS);
    card.className = "node-card node-card--theme";
    if (p.is_focus) card.classList.add("node-card--focus");
    // #61: fade non-matching cards when a search query is active.
    if (matchSet && !matchSet.has(p.id)) card.classList.add("node-card--filtered");
    // Mode-specific visual hooks computed by computeModeData(). The
    // SVG-level data attribute (set after this loop) decides whether the
    // CSS rules light up; here we just expose the per-card signals.
    const modeMeta = state.modeData?.get(p.id);
    if (modeMeta?.kind === "tier" && modeMeta.value) {
      card.dataset.tier = String(modeMeta.value);
    } else if (modeMeta?.kind === "novelty" && modeMeta.value !== "neutral") {
      card.dataset.novelty = modeMeta.value;
    } else if (modeMeta?.kind === "lineage" && typeof modeMeta.value === "number") {
      card.style.setProperty("--lineage-hue", String(modeMeta.value));
    }
    // #67: citation-heat — log-normalised 0..1 weight that the CSS
    // turns into border thickness + halo intensity. 500k cite ceiling
    // matches the most-cited DL papers (~226k for ResNet, ~174k for
    // Attention). Use --card-heat as a CSS custom property so styles
    // can compose it however they want.
    const cit = typeof p.citation_count === "number" ? p.citation_count : 0;
    const heat = cit > 0 ? Math.min(1, Math.log10(cit + 1) / Math.log10(500001)) : 0;
    card.style.setProperty("--card-heat", heat.toFixed(3));

    const tier = p.venue_tier === "A+" ? "aplus" : p.venue_tier === "A" ? "a" : "preprint";
    const venue = PP.formatVenue(p.venue, p.year);
    const authors = (p.authors || []).slice(0, 3).join(", ")
      + ((p.authors || []).length > 3 ? ` +${p.authors.length - 3}` : "");
    const cits = typeof p.citation_count === "number" && p.citation_count > 0
      ? `<span class="node-card__cit">📖 ${p.citation_count.toLocaleString()}</span>` : "";
    const stars = formatStars(p.github_stars);
    const starsHtml = stars ? `<span class="node-card__stars">⭐${stars}</span>` : "";
    // Build a paper URL — prefer arXiv (immediate PDF), then DOI (publisher
    // page), and fall back to Semantic Scholar's detail page when neither
    // is on the node. arXiv ids may include a version suffix like
    // "1610.04256v2" — strip nothing; arxiv.org accepts both forms.
    let paperUrl = `https://www.semanticscholar.org/paper/${encodeURIComponent(p.id)}`;
    // ARXIV_RE / DOI_RE are hoisted to module scope (above) — strict
    // forms ensure the id we splice into the link is shape-correct
    // before encodeURIComponent runs.
    if (p.arxiv_id && ARXIV_RE.test(p.arxiv_id)) {
      paperUrl = `https://arxiv.org/abs/${encodeURIComponent(p.arxiv_id)}`;
    } else if (p.doi && DOI_RE.test(p.doi)) {
      paperUrl = `https://doi.org/${encodeURIComponent(p.doi)}`;
    }
    // #63: TLDR is the abstract head ≤ 140 chars — show it 2-line-clamped
    // under the title so users can size up a paper without clicking.
    const tldrHtml = p.tldr
      ? `<div class="node-card__tldr">${escapeHtml(p.tldr)}</div>`
      : "";
    // #68: trending badge for fast-moving papers (citation velocity).
    const trendingHtml = p.is_trending
      ? `<span class="node-card__trending" title="citation velocity: trending">📈</span>`
      : "";
    // #83: hub badge for papers whose in+out degree clears the 90th
    // percentile across the theme. Strong cross-tree connectors —
    // worth a glance whether or not citation_count is high.
    const isHub = state.hubSet?.has(p.id);
    if (isHub) card.classList.add("node-card--hub");
    const hubHtml = isHub
      ? `<span class="node-card__hub" title="hub paper: high connectivity">👑</span>`
      : "";
    card.innerHTML = `
      <div class="node-card__venue">
        <span class="node-card__venue-tier node-card__venue-tier--${tier}">${escapeHtml(venue || "—")}</span>
        ${hubHtml}
        ${trendingHtml}
      </div>
      <h3 class="node-card__title">${escapeHtml(p.title || "")}</h3>
      ${tldrHtml}
      <div class="node-card__authors">${escapeHtml(authors)}</div>
      <div class="node-card__meta">${cits}${starsHtml}</div>
    `;

    // Hover: highlight edges incident to this node, fade the rest. Done
    // by toggling .is-faded on every edge that doesn't touch this id.
    card.addEventListener("mouseenter", () => {
      highlightNode(p.id);
      schedulePopover(p, card);
    });
    card.addEventListener("mouseleave", () => {
      clearHighlight();
      hidePopover();
    });
    // Click: open the paper page in a new tab. arxiv > doi > S2 fallback
    // gives readers the most direct route to the actual paper.
    card.addEventListener("click", () => {
      window.open(paperUrl, "_blank", "noopener,noreferrer");
    });
    card.style.cursor = "pointer";
    const tooltipBase = p.arxiv_id ? "arXiv"
                      : p.doi ? "DOI"
                      : "Semantic Scholar";
    card.title = `クリックで ${tooltipBase} に開く`;

    fo.appendChild(card);
    wrap.appendChild(fo);
    ng.appendChild(wrap);
  }
  els.svg.appendChild(ng);

  // FLIP: for nodes that survived the render, snap them back to their
  // OLD position with the transition disabled, then on the next paint
  // remove the override so the CSS transition glides them to the new
  // position. Skips work if reduced-motion is on, or if there's nothing
  // to compare against (first render).
  if (oldPositions.size > 0
      && !window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
    const moves = [];
    for (const wrap of ng.querySelectorAll("g.node-wrap[data-node-id]")) {
      const id = wrap.dataset.nodeId;
      const old = oldPositions.get(id);
      if (!old) continue;
      const tr = wrap.getAttribute("transform") || "";
      const m = tr.match(/translate\(\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*\)/);
      if (!m) continue;
      const nx = parseFloat(m[1]);
      const ny = parseFloat(m[2]);
      if (Math.abs(nx - old.x) < 0.5 && Math.abs(ny - old.y) < 0.5) continue;
      moves.push({ wrap, old, target: { x: nx, y: ny } });
    }
    for (const { wrap, old } of moves) {
      wrap.classList.add("node-wrap--no-tx");
      wrap.setAttribute("transform", `translate(${old.x}, ${old.y})`);
    }
    // Force layout flush so the no-transition style is applied before
    // we revert. getBoundingClientRect() is the standard "make the
    // browser commit current styles right now" idiom.
    if (moves.length > 0) void els.svg.getBoundingClientRect();
    requestAnimationFrame(() => {
      for (const { wrap, target } of moves) {
        wrap.classList.remove("node-wrap--no-tx");
        wrap.setAttribute("transform", `translate(${target.x}, ${target.y})`);
      }
    });
  }

  // #66: paint the minimap with the same node positions, then bind
  // click/drag and a window-scroll viewport tracker. Late so coords
  // are up-to-date.
  drawMinimap(positioned, totalW, totalH);
}

// #66: minimap — a small canvas that mirrors the SVG's node positions at
// scale, draws the current viewport rect, and lets the user click or drag
// to pan. State holds a pre-rendered "dots only" canvas so scroll only
// re-paints the viewport rectangle (cheap; no DOM rebuild).
let minimapState = null;
function drawMinimap(positioned, totalW, totalH) {
  if (!els.minimap || !els.minimapCanvas) return;
  // Hide the minimap when the SVG already fits in the viewport — no nav needed.
  const needsMinimap = totalW > window.innerWidth + 100
    || totalH > window.innerHeight + 100;
  els.minimap.hidden = !needsMinimap;
  if (!needsMinimap) {
    minimapState = null;
    return;
  }
  const cv = els.minimapCanvas;
  const cw = cv.width, ch = cv.height;
  const s = Math.min(cw / totalW, ch / totalH);
  const ox = (cw - totalW * s) / 2;
  const oy = (ch - totalH * s) / 2;

  // Render the static dot layer once into an offscreen canvas. Scroll
  // updates only blit this image then draw the viewport rect on top.
  const dotsLayer = document.createElement("canvas");
  dotsLayer.width = cw;
  dotsLayer.height = ch;
  const dctx = dotsLayer.getContext("2d");
  dctx.fillStyle = "rgba(255, 250, 240, 0.95)";
  dctx.fillRect(0, 0, cw, ch);
  dctx.fillStyle = "rgba(80, 60, 40, 0.55)";
  for (const n of positioned) {
    const x = ox + (n._x + NODE_W / 2) * s;
    const y = oy + (n._y + NODE_H / 2) * s;
    dctx.fillRect(x - 1.5, y - 1.5, 3, 3);
  }

  minimapState = { totalW, totalH, s, ox, oy, dotsLayer };
  drawMinimapViewport();
}

function drawMinimapViewport() {
  if (!minimapState || !els.minimapCanvas) return;
  const cv = els.minimapCanvas;
  const ctx = cv.getContext("2d");
  const { s, ox, oy, dotsLayer } = minimapState;

  // Blit the cached dot layer (constant-cost paint).
  ctx.drawImage(dotsLayer, 0, 0);

  // Viewport rect — clipped to the canvas bounds.
  const vx = ox + window.scrollX * s;
  const vy = oy + window.scrollY * s;
  const vw = window.innerWidth * s;
  const vh = window.innerHeight * s;
  const rx = Math.max(0, Math.min(cv.width, vx));
  const ry = Math.max(0, Math.min(cv.height, vy));
  const rw = Math.max(0, Math.min(cv.width - rx, vw));
  const rh = Math.max(0, Math.min(cv.height - ry, vh));
  ctx.fillStyle = "rgba(255, 110, 0, 0.10)";
  ctx.strokeStyle = "oklch(58% 0.18 30)";
  ctx.lineWidth = 1.5;
  ctx.fillRect(rx, ry, rw, rh);
  ctx.strokeRect(rx, ry, rw, rh);
}

// Click / drag the minimap to pan the page.
function onMinimapPointer(ev) {
  if (!minimapState) return;
  const rect = els.minimapCanvas.getBoundingClientRect();
  // Account for any CSS scaling between the canvas's intrinsic px and
  // its layout box.
  const scaleX = els.minimapCanvas.width / rect.width;
  const scaleY = els.minimapCanvas.height / rect.height;
  const px = (ev.clientX - rect.left) * scaleX;
  const py = (ev.clientY - rect.top) * scaleY;
  const { s, ox, oy } = minimapState;
  const targetX = (px - ox) / s - window.innerWidth / 2;
  const targetY = (py - oy) / s - window.innerHeight / 2;
  window.scrollTo({
    left: Math.max(0, targetX),
    top: Math.max(0, targetY),
    behavior: "smooth",
  });
}

if (els.minimapCanvas) {
  let dragging = false;
  els.minimapCanvas.addEventListener("mousedown", (ev) => {
    dragging = true;
    onMinimapPointer(ev);
  });
  els.minimapCanvas.addEventListener("mousemove", (ev) => {
    if (dragging) onMinimapPointer(ev);
  });
  window.addEventListener("mouseup", () => { dragging = false; });
  let scrollPending = false;
  window.addEventListener("scroll", () => {
    if (!minimapState || scrollPending) return;
    scrollPending = true;
    requestAnimationFrame(() => {
      drawMinimapViewport();
      scrollPending = false;
    });
  }, { passive: true });
}

function highlightNode(nodeId) {
  const eg = document.getElementById("edges");
  if (!eg) return;
  // Re-use the lineage viewer's existing edge--highlight / edge--dim
  // CSS classes so the visual treatment stays consistent across viewers.
  const peers = new Set([nodeId]);
  for (const path of eg.querySelectorAll("path.edge")) {
    const src = path.dataset.src;
    const dst = path.dataset.dst;
    if (src === nodeId || dst === nodeId) {
      path.classList.add("edge--highlight");
      path.classList.remove("edge--dim");
      peers.add(src);
      peers.add(dst);
    } else {
      path.classList.add("edge--dim");
      path.classList.remove("edge--highlight");
    }
  }
  for (const fo of document.querySelectorAll("foreignObject[data-node-id]")) {
    const id = fo.dataset.nodeId;
    const card = fo.firstChild;
    if (!card) continue;
    if (id === nodeId) {
      card.classList.add("node-card--peer-self");
    } else if (peers.has(id)) {
      card.classList.add("node-card--peer");
    } else {
      card.classList.add("node-card--dimmed");
    }
  }
}

// #69: card hover popover. Card body shows the 2-line clamped TLDR;
// hover for 700ms surfaces the full title + abstract head + authors
// in a side panel so readers can verify a paper before clicking.
let popoverTimer = null;
function schedulePopover(node, cardEl) {
  clearTimeout(popoverTimer);
  popoverTimer = setTimeout(() => showPopover(node, cardEl), 700);
}
function showPopover(node, cardEl) {
  if (!els.popover) return;
  if (els.popVenue) {
    els.popVenue.textContent = PP.formatVenue(node.venue, node.year) || "—";
  }
  if (els.popTitle) els.popTitle.textContent = node.title || "";
  if (els.popTldr) els.popTldr.textContent = node.tldr || "";
  if (els.popAuthors) {
    els.popAuthors.textContent = (node.authors || []).join(", ");
  }
  if (els.popMeta) {
    const cit = typeof node.citation_count === "number" && node.citation_count > 0
      ? `📖 ${node.citation_count.toLocaleString()}` : "";
    const stars = formatStars(node.github_stars);
    const link = node.arxiv_id ? `arXiv:${node.arxiv_id}`
                : node.doi ? `DOI:${node.doi}`
                : "";
    els.popMeta.textContent = [cit, stars && `⭐${stars}`, link]
      .filter(Boolean).join("  ·  ");
  }
  // Position next to the card — prefer the right side; fall back to left
  // when there's no room. Coords are in page space.
  const rect = cardEl.getBoundingClientRect();
  const popW = 360, popH = 220, gap = 12;
  let x = rect.right + gap + window.scrollX;
  let y = rect.top + window.scrollY;
  if (x + popW > window.scrollX + window.innerWidth - 12) {
    x = rect.left + window.scrollX - popW - gap;
  }
  if (x < window.scrollX + 12) x = window.scrollX + 12;
  if (y + popH > window.scrollY + window.innerHeight - 12) {
    y = window.scrollY + window.innerHeight - popH - 12;
  }
  if (y < window.scrollY + 12) y = window.scrollY + 12;
  els.popover.style.left = `${x}px`;
  els.popover.style.top = `${y}px`;
  els.popover.setAttribute("aria-hidden", "false");
  els.popover.classList.add("card-popover--visible");
}
function hidePopover() {
  clearTimeout(popoverTimer);
  if (!els.popover) return;
  els.popover.setAttribute("aria-hidden", "true");
  els.popover.classList.remove("card-popover--visible");
}

function clearHighlight() {
  for (const path of document.querySelectorAll("#edges path.edge")) {
    path.classList.remove("edge--highlight", "edge--dim");
  }
  for (const fo of document.querySelectorAll("foreignObject[data-node-id]")) {
    const card = fo.firstChild;
    if (!card) continue;
    card.classList.remove("node-card--peer-self", "node-card--peer", "node-card--dimmed");
  }
}

// ---- Tooltip ----

function onEdgeHover(e) {
  const rel = e.currentTarget.dataset.rel || "";
  els.ttRel.textContent = rel.replace("_", " ");
  // textContent (NOT innerHTML): rationale comes from an LLM and must be
  // treated as untrusted text. innerHTML here would be an XSS sink.
  els.ttRationale.textContent = e.currentTarget.dataset.rationale || "";
  const c = e.currentTarget.dataset.conf;
  els.ttConf.textContent = c ? `confidence ${Number(c).toFixed(2)}` : "";
  els.tooltip.classList.add("is-visible");
  els.tooltip.setAttribute("aria-hidden", "false");
  onEdgeMove(e);
}
function onEdgeMove(e) {
  const tt = els.tooltip; const pad = 12;
  let x = e.clientX + pad, y = e.clientY + pad;
  const w = tt.offsetWidth || 280, h = tt.offsetHeight || 80;
  if (x + w > window.innerWidth - 8) x = e.clientX - w - pad;
  if (y + h > window.innerHeight - 8) y = e.clientY - h - pad;
  tt.style.left = `${Math.max(8, x)}px`;
  tt.style.top = `${Math.max(8, y)}px`;
}
function onEdgeLeave() {
  els.tooltip.classList.remove("is-visible");
  els.tooltip.setAttribute("aria-hidden", "true");
}

init();
